#!/usr/bin/env bash
# Resolve the shared-output conflicts of this branch against origin/main by UNION.
#
# The root navigation (index.html) and COORDINATION.md are shared outputs. Other
# sessions edit them while this branch is open, so a rebase always conflicts
# there. This script resolves both by union, never by discarding peer work:
#
#   COORDINATION.md  = origin/main's full history + this session's record block,
#                      re-appended at the end.
#   index.html       = origin/main's file, then regenerated by build_root.py,
#                      which preserves every peer navigation entry verbatim.
#
# Usage: bash nfl-hq/rebase_union.sh
set -euo pipefail

cd "$(git rev-parse --show-toplevel)"

BLOCK=/tmp/7f2d46fa-coordination-block.md
MARKER='## Session `arena/7f2d46fa-own4` — FINAL INTEGRATION'

# 1. save this session's coordination record before overwriting the file
python3 - "$MARKER" "$BLOCK" <<'PY'
import sys

marker, out = sys.argv[1], sys.argv[2]
try:
    text = open("COORDINATION.md", encoding="utf-8").read()
except OSError:
    text = ""
i = text.find(marker)
open(out, "w", encoding="utf-8").write(text[i:] if i >= 0 else "")
print("saved coordination block:", (len(text[i:]) if i >= 0 else 0), "chars")
PY

# 2. union for the shared files
git show origin/main:COORDINATION.md > COORDINATION.md
python3 - "$MARKER" "$BLOCK" <<'PY'
import sys

marker, block_path = sys.argv[1], sys.argv[2]
main = open("COORDINATION.md", encoding="utf-8").read()
block = open(block_path, encoding="utf-8").read().strip()
i = main.find(marker)
if i >= 0:                      # do not duplicate if a peer carried it forward
    head = main[:i]
else:
    head = main
if not head.endswith("\n"):
    head += "\n"
if block:
    head += "\n" + block + "\n"
open("COORDINATION.md", "w", encoding="utf-8").write(head)
print("coordination union written; session sections:",
      head.count("\n## Session"))
PY

git show origin/main:index.html > index.html

# 3. finish the rebase step
git add -A .
GIT_EDITOR=true git rebase --continue

# 4. regenerate everything from committed inputs and verify
python3 nfl-hq/build_data.py
for _ in 1 2 3; do
  python3 nfl-hq/verify_site.py || true
  python3 nfl-hq/build_site.py
  python3 nfl-hq/build_root.py
done
python3 nfl-hq/verify_site.py

# 5. prove no peer navigation link was dropped
python3 - <<'PY'
import re
import subprocess

old = subprocess.run(["git", "show", "origin/main:index.html"],
                     capture_output=True, text=True).stdout


def hrefs(s):
    m = re.search(r"<nav.*?</nav>", s, re.S)
    return set(re.findall(r'href="([^"]+)"', m.group(0) if m else s))


new = hrefs(open("index.html", encoding="utf-8").read())
missing = sorted(hrefs(old) - new)
print("peer nav hrefs on main:", len(hrefs(old)),
      "| after union:", len(new), "| missing:", missing)
if missing:
    raise SystemExit("peer navigation lost: %s" % missing)
PY
